  "plans.mobileIncludedNote": "দুটি ওয়েবসাইট পরিকল্পনাতেই মোবাইল সঙ্গী অন্তর্ভুক্ত, তাই ওয়েবসাইটের গ্রাহককে মাসিক মোবাইল ফি আলাদা করে দিতে হয় না।",
  "plans.priceNote": "Essentials $14.99/মাস সঙ্গে প্রযোজ্য কর, যদি থাকে। Business $29.99/মাস সঙ্গে প্রযোজ্য কর, যদি থাকে। প্রয়োজনীয় কর প্রদানকারীর চেকআউটের সময় নির্ধারিত হয় এবং পেমেন্টের আগে চূড়ান্ত মোট অঙ্কে দেখাতে হবে। এই তুলনার পাতাটি করের উদ্ধৃতি বা পেমেন্টের অনুমোদন নয়।",
  "plans.mobilePriceNote": "মোবাইল-শুধু পরিকল্পনাটি তার নির্ধারিত মার্কিন মূল্যে $4.99/মাস। App Store বা Google Play কেনার আগে প্রকৃত স্থানীয় সাবস্ক্রিপশন মূল্য ও প্রযোজ্য কর দেখায়। এর পণ্য, সাইট ও কর্মী সীমা লঞ্চের সময় নির্ধারিত হয়, ওয়েবসাইট স্তরগুলো থেকে আলাদাভাবে।",
  "plans.planChangeNote": "ওয়েবসাইট পরিকল্পনার পরিবর্তন বিলিং প্রদানকারীর দ্বারা নিশ্চিত হতে হবে। নতুন মূল্য, কার্যকর তারিখ ও প্রযোজ্য প্রোরেশন পরিবর্তন অনুমোদন করার আগে ব্যাখ্যা করা হবে। আপগ্রেডে দ্বিতীয় সাবস্ক্রিপশন তৈরি হওয়া উচিত নয়।",
  "plans.providerNote": "দাম, চার্জ ও ট্রায়াল সেই প্রদানকারী পরিচালনা করে যার মাধ্যমে আপনি সাবস্ক্রাইব করেন — App Store, Google Play, ওয়েবসাইট বা Shopify — এই পাতা কখনো নয়।",
