  "billing.cancel.alreadyCanceledWithEnd": "এটি {date} শেষ হয়। ততক্ষণ পর্যন্ত আপনার সম্পূর্ণ সুবিধা থাকে। ওই তারিখের পর আপনার পণ্যগুলো দেখার জন্য {graceDays} দিনের শুধু-পড়ার গ্রেস সময় থাকে। {wipeSentence}",
  "billing.cancel.alreadyCanceledNoEnd": "এটি বর্তমান অর্থপ্রদত্ত সময়ের শেষে শেষ হয়। ততক্ষণ পর্যন্ত আপনার সম্পূর্ণ সুবিধা থাকে।",
  "billing.cancel.appStoreNote": "আপনি যদি কখনো Google Play বা Apple App Store-এর মাধ্যমে সাবস্ক্রাইব করেন, তাহলে ওই স্টোরের সাবস্ক্রিপশন সেটিংসের মাধ্যমে তা বাতিল করতে হতে পারে। এই ডায়ালগ অ্যাপ-স্টোরের বিলিং থামাতে পারে না। অ্যাপ আনইনস্টল করলে বা আপনার StockHaven অ্যাকাউন্ট মুছে ফেললে স্টোরের সাবস্ক্রিপশন বাতিল হয় না।",
  "billing.cancel.trialNote": "ট্রায়াল চলাকালীন বাতিল করলে আপনার পুরো 7 দিন থাকে — সুবিধা {date} শেষ হয়, এবং আপনার কাছ থেকে টাকা নেওয়া হবে না।",
