  "billing.cancel.keepAccessRest": "বাতিল করলে কেবল ভবিষ্যতের নবায়ন বন্ধ হয় — এতে আপনার সুবিধা একসঙ্গে শেষ হয় না, এবং কোনো অতিরিক্ত বিনামূল্যের মাস যোগ হয় না।",
  "billing.cancel.gracePeriodTitle": "ওই তারিখের পর, {graceDays} দিনের শুধু-পড়ার গ্রেস সময়।",
  "billing.cancel.gracePeriodRest": "আপনি তখনো লগ ইন করে আপনার পণ্যগুলো দেখতে পারেন, যাতে আপনি যা ছিল তা দেখে লিখে নিতে পারেন। বাকি সবকিছু বন্ধ থাকে: যোগ করা, সম্পাদনা করা, মোছা, স্ক্যান করা, ইমপোর্ট, এক্সপোর্ট বা মাইগ্রেশন নয়, সেটিংস নয়, কর্মী নয়।",
  "billing.cancel.resubscribeFresh": "আবার সাবস্ক্রাইব করলে নতুন করে শুরু হয়।",
  "billing.cancel.refundsSeparate": "ফেরত আলাদা বিষয়।",
  "billing.cancel.refundsRest": "বাতিল করলেই ফেরত দেওয়া হয় না। প্রথম পেমেন্টের ফেরত প্রযোজ্য হয় কেবল তখনই যখন আপনি প্রথম সফল অর্থপ্রদত্ত চার্জের 3 দিনের (72 ঘণ্টা) মধ্যে বাতিল করেন, {contact}-এর মাধ্যমে অনুরোধ করলে।",
