  "billing.readiness.complimentaryProtected": "আপনার বিনামূল্যের Business ওয়ার্কস্পেস সুরক্ষিত। এটি অর্থপ্রদত্ত Essentials পরীক্ষার অ্যাকাউন্ট হওয়া উচিত নয়।",
