  "reports.footnote": "বিক্রয়ে প্রতিটি পণ্যের বর্তমান খুচরা মূল্য ব্যবহার করা হয়, রসিদে স্টক আসার সময় রেকর্ড করা খরচ ব্যবহার করা হয়, আর ক্ষতিতে বর্তমান ইউনিট খরচ ব্যবহার করা হয়। অনুপস্থিত অর্থ কখনো শূন্য ধরা হয় না — জানা না যাওয়া পর্যন্ত একটি ফিল্ড ফাঁকা রাখুন। রিপোর্ট একটি ভিউ, দলিল নয়: এটি চালালে আপনার রেকর্ডে কিছুই লেখা হয় না।",
  "reports.createBusinessFirst": "আগে একটি ব্যবসা তৈরি করুন — রিপোর্ট প্রতিটি ব্যবসার জন্য আলাদাভাবে গোনা হয়।",
