  "settings.cancelSubscription": "সাবস্ক্রিপশন বাতিল করুন",
  "settings.cancelTerms.appleLink": "Apple বাতিলের নির্দেশনা",
  "settings.cancelTerms.googlePlayLink": "Google Play বাতিলের নির্দেশনা",
  "settings.cancelTerms.graceTitle": "আপনার পেইড মেয়াদ শেষ হওয়ার পর — 15 দিনের গ্রেস, তারপর মুছে ফেলা:",
  "settings.cancelTerms.intro": "এগুলো পেইড Luminous StockHaven সাবস্ক্রিপশনের শর্তাবলি। ওয়েবসাইট সাবস্ক্রিপশনের বিলিং Stripe-এর মাধ্যমে হয়। নিচের Cancel Subscription বোতাম দিয়ে আপনি যেকোনো সময় নিজেই আপনার সাবস্ক্রিপশন বাতিল করতে পারেন — কর্মীদের অনুমোদনের প্রয়োজন নেই। বাতিল ও ফেরতের অনুরোধ অফিসিয়াল কাস্টমার সাপোর্ট যোগাযোগ, theluminousbookshop@outlook.com-এর মাধ্যমেও করা যায়।",
  "settings.cancelTerms.noApprovalBody": "আপনি যেকোনো সময় নিজেই আপনার সাবস্ক্রিপশন বাতিল করতে পারেন। কর্মীদের অনুমোদনের প্রয়োজন নেই। বিলিং প্রদানকারী বাতিল নিশ্চিত করার পরই ভবিষ্যতের নবায়ন বন্ধ হয়।",
  "settings.cancelTerms.noApprovalTitle": "অনুমোদন ছাড়াই বাতিল করুন:",
  "settings.cancelTerms.paymentBody": "পেইড ট্রায়ালের ক্ষেত্রে সাত দিনের ট্রায়ালে সাইনআপের সময় পেমেন্ট পদ্ধতি দিতে হয়। প্রযোজ্য ট্রায়াল বাতিলের সময়সীমার মধ্যে বাতিল না করলে ট্রায়ালের পর নির্বাচিত মাসিক প্ল্যানের চার্জ স্বয়ংক্রিয়ভাবে কাটা হবে। সাইনআপের সময় মূল্য, প্রথম বিলিং তারিখ এবং প্রদানকারী-নির্দিষ্ট বাতিলের সময়সীমা দেখাতে হবে। ট্রায়ালের বিলিং Stripe-এর মাধ্যমে হয়।",
  "settings.cancelTerms.paymentTitle": "পেমেন্ট পদ্ধতি ও স্বয়ংক্রিয় নবায়ন:",
  "settings.cancelTerms.remainingBody": "আপনি যদি ইতিমধ্যে একটি বিলিং মেয়াদের জন্য পেমেন্ট করে থাকেন, যাচাইকৃত পেইড-থ্রু তারিখ পর্যন্ত আপনি অ্যাক্সেস ধরে রাখতে পারেন। আগাম সমাপ্তির জন্য প্রদানকারীর যথাযথ নিশ্চিতকরণ ও প্রযোজ্য ফেরত প্রক্রিয়া প্রয়োজন। বিনামূল্যের ট্রায়ালের অ্যাক্সেস প্রদানকারী-নিশ্চিত ট্রায়াল সমাপ্তির তারিখ অনুযায়ী শেষ হয়।",
  "settings.cancelTerms.remainingTitle": "বাকি অ্যাক্সেস:",
  "settings.cancelTerms.storesBody": "আপনি যদি কখনো Google Play বা Apple App Store-এর মাধ্যমে সাবস্ক্রাইব করেন, আপনার সাবস্ক্রিপশন সেই স্টোরই বিল করে ও পরিচালনা করে। সাবস্ক্রাইব করতে ব্যবহৃত একই Google বা Apple অ্যাকাউন্টের সাবস্ক্রিপশন বিভাগে গিয়ে সরাসরি বাতিল করতে হতে পারে। আলাদা ওয়েবসাইট সাবস্ক্রিপশন বাতিল করা, এই অ্যাপ আনইনস্টল করা, বা Luminous StockHaven অ্যাকাউন্ট মুছে ফেলার অনুরোধ করলে স্টোর-বিল করা সাবস্ক্রিপশন স্বয়ংক্রিয়ভাবে বাতিল হয় না। কে আপনাকে বিল করে তা নিশ্চিত করতে আপনার ক্রয়ের রসিদ দেখুন।",
  "settings.cancelTerms.storesTitle": "Google Play ও Apple App Store সাবস্ক্রিপশন (যদি কখনো কোনো স্টোরের মাধ্যমে সাবস্ক্রাইব করেন):",
  "settings.cancelTerms.title": "বাতিলের শর্তাবলি",
  "settings.cancelTerms.trialBody": "সাত দিনের ট্রায়াল প্রত্যেক যোগ্য গ্রাহক শুধু একবারই ব্যবহার করতে পারেন। ট্রায়াল বা সাবস্ক্রিপশন বাতিল করলে আরেকটি ট্রায়াল পাওয়া যায় না; ফিরে আসা গ্রাহকদের পেইড সাবস্ক্রিপশন বেছে নিতে হবে।",
  "settings.cancelTerms.trialTitle": "একটি বিনামূল্যের ট্রায়াল:",
  "settings.canceled.endsOn": "এই সাবস্ক্রিপশন বাতিল হয়েছে এবং {date}-এ শেষ হবে। ততদিন পর্যন্ত আপনার সম্পূর্ণ অ্যাক্সেস থাকবে।",
  "settings.delete.checking": "বিদ্যমান মুছে ফেলার অনুরোধ আছে কি না যাচাই করা হচ্ছে…",
  "settings.delete.description": "আপনার Luminous StockHaven সাইন-ইন অ্যাকাউন্ট অপসারণের অনুরোধ করুন।",
  "settings.delete.dialogDescription": "এটি অ্যাকাউন্ট মুছে ফেলার পর্যালোচনার অনুরোধ করে। এটি সঙ্গে সঙ্গে আপনার লগইন বা ইনভেন্টরি সরায় না, এবং কোনো Stripe সাবস্ক্রিপশন বাতিল করে না। অনুরোধ জমা দিতে চান তা নিশ্চিত করতে {word} লিখুন।",
  "settings.delete.dialogTitle": "অ্যাকাউন্ট মুছে ফেলার অনুরোধ",
