  "settings.delete.notDeleted": "এই অনুরোধে আপনার অ্যাকাউন্ট ও ডেটা মুছে ফেলা হয়নি। বিলিং বাতিল হয়নি।",
  "settings.delete.received": "আপনার অ্যাকাউন্ট মুছে ফেলার অনুরোধ পাওয়া গেছে।",
  "settings.delete.requestButton": "অ্যাকাউন্ট মুছে ফেলার অনুরোধ করুন",
