  "staff.access.signOut": "সাইন আউট",
  "staff.access.suspendedBody": "একজন অ্যাডমিনিস্ট্রেটর সক্রিয় ব্যবসার জন্য এই কর্মী অ্যাকাউন্টটি স্থগিত করেছেন। তাদের বলুন আপনাকে আবার সক্রিয় করতে, তারপর আবার সাইন ইন করুন।",
  "staff.access.suspendedTitle": "আপনার অ্যাক্সেস স্থগিত আছে",
  "staff.addFirst": "প্রথম কর্মী যোগ করুন",
