  "staff.emptyBody": "একজন ব্যক্তি যোগ করুন, তাকে একটি ভূমিকা ও তার সঙ্গে যাওয়া অনুমতিগুলো দিন, আর তিনি ইমেইলে আমন্ত্রণ পেয়ে এই ব্যবসায় সাইন ইন করবেন।",
  "staff.emptyTitle": "এখনো কোনো কর্মী নেই",
  "staff.eyebrow": "দল",
  "staff.how.p1": "প্রত্যেক সদস্যের একটি ভূমিকা ও নিজস্ব অনুমতির তালিকা আছে, তাই আপনি একটি ভূমিকা থেকে শুরু করে নতুন ভূমিকা না বানিয়ে একটি জিনিস বদলাতে পারেন। ভূমিকা সম্পাদনা করলে ইতিমধ্যে সেই ভূমিকায় থাকা সদস্যরা বদলে যায় না — তাদের ভূমিকার ডিফল্ট আবার প্রয়োগ করতে একজন সদস্যকে খুলুন।",
  "staff.how.p2": "কাস্টম ভূমিকা একটি Business সুবিধা: Essentials পাঁচটি বিল্ট-ইন ভূমিকা ব্যবহার করে (Owner, Manager, Stock clerk, Sales clerk, Viewer)।",
  "staff.how.p3": "আমন্ত্রণ ইমেইলে পাঠানো হয়। একজন সদস্য গ্রহণ করার পরই সাইন ইন করতে পারেন, এবং এই তালিকা থেকে কাউকে সরালে তার অ্যাপ অ্যাকাউন্ট মুছে যায় না।",
  "staff.how.p4": "স্টোর হলো সেই অবস্থান যেখানে একজন ব্যক্তিকে নিয়োগ করা হয়। এটি তার কার্ডে লেখা থাকে; তিনি কী খুলতে পারবেন তা তবুও তার ভূমিকা ও অনুমতি দিয়ে নির্ধারিত হয়।",
  "staff.how.p5": "অনুমতি নির্ধারণ করে প্রত্যেকে কী খুলতে পারবে: ভূমিকার বাইরের মেনু আইটেম লুকিয়ে থাকে, এবং বন্ধ ঠিকানায় পৃষ্ঠার বদলে “আপনার ভূমিকায় নেই” নোটিশ দেখা যায়। পরিবর্তন প্রযোজ্য হয় ওই ব্যক্তি পরের বার অ্যাপ লোড করলে; সদস্যকে স্থগিত করলে তিনি সম্পূর্ণভাবে বাইরে থাকেন।",
  "staff.how.p6": "অ্যাডমিনিস্ট্রেটররা সব ডেটা দেখতে ও বদলাতে পারেন, অ্যাপ ব্যবহারকারী ও ভূমিকা পরিচালনা করতে পারেন, এবং কর্মী ভূমিকা দিয়ে কখনো সীমাবদ্ধ হন না। যার কোনো কর্মী রেকর্ড নেই — নতুন ব্যবসার মালিক — তিনি সম্পূর্ণ অ্যাক্সেস ধরে রাখেন।",
  "staff.howTitle": "কর্মী ও ভূমিকা কীভাবে কাজ করে",
