  "payroll.dd.steps.body": "1. আপনার একটি ব্যবসায়িক ব্যাংক অ্যাকাউন্ট দরকার যা ACH পেমেন্ট পাঠাতে পারে। 2. প্রতিটি দলের সদস্যের কাছ থেকে স্বাক্ষরিত অনুমোদন ফর্ম সংগ্রহ করুন — একটি বাতিল চেক নম্বরগুলো যাচাই করতে সাহায্য করে। 3. বেতনের দিনের 2-3 কর্মদিবস আগে পেরোল পাঠান যাতে টাকা সময়মতো পৌঁছায়। 4. বেশিরভাগ রাজ্যে দলের সদস্যের লিখিত সম্মতি প্রয়োজন। এই অ্যাপ ফর্মগুলো সংগ্রহ করে এবং ধাপগুলোতে আপনাকে পথ দেখায় — আসলে টাকা পাঠানো হয় আপনার নিজের ব্যাংকের মাধ্যমে।",
