  "workforce.messages.emptyThread": "এখনো কোনো বার্তা নেই। শুরু করতে হ্যালো বলুন।",
  "workforce.messages.help": "আপনার দলের সঙ্গে ব্যক্তিগত এক-এক বার্তা — অন্য কোনো অ্যাপের প্রয়োজন নেই। একটি কথোপকথনের দুজন ব্যক্তিই কেবল তা পড়তে পারেন, এবং ব্যবসার মালিক, যিনি তার স্টোর তদারকি করেন।",
