  "auth.sameEmailNotice": "Google Play বা App Store থেকে ইতিমধ্যে আমাদের অ্যাপ আছে? এখানে সেই একই ইমেইল ব্যবহার করুন — যেটি দিয়ে আপনি অ্যাপে সাইন ইন করেন — যাতে আপনার দোকান ও আপনার ইনভেন্টরি আপনার সঙ্গে আসে। একটি ভিন্ন ইমেইল একটি সম্পূর্ণ নতুন, খালি স্টোরফ্রন্ট শুরু করে।",
