  "recovery.emailMeCodeHint": "আপনি একটি ব্যাকআপ ইমেইল সেট আপ করে থাকলে, আমরা সেখানে একটি 6 সংখ্যার কোড পাঠাব। আপনার অ্যাকাউন্ট রক্ষা করতে, এই পাতা সবসময় একইভাবে উত্তর দেয় — কোড পাঠানো হোক বা না হোক।",
