  "recovery.changeIntro": "আপনি ভেতরে আছেন — কেবল একটি ধাপের জন্য: আপনার অ্যাকাউন্টের জন্য নতুন ইমেইল বেছে নিন। আপনার দোকান, আপনার ইনভেন্টরি ও আপনার দলের প্রবেশ সবই এর সঙ্গে সরে।",
  "recovery.doneBody": "আপনার অ্যাকাউন্ট ইমেইল বদলানো হয়েছে এবং এই সাইন-ইন এখন আবার আপনার নিয়মিত সাইন-ইন। ফিরে আসায় স্বাগতম।",
