  "settings.security.backupCodesDesc": "একবার ব্যবহারযোগ্য অতিরিক্ত চাবি। সেগুলো মুদ্রণ করুন বা লিখে রাখুন এবং নিরাপদ কোথাও রাখুন — আপনি আপনার ইমেইল হারালে প্রতিটি আপনাকে একবার ফিরিয়ে আনতে পারে।",
