  "rewards.give.detail": "পুরস্কারটি কী?",
  "rewards.give.detailPlaceholder": "আপনার নিজের কথায় পুরস্কারটি বর্ণনা করুন",
  "rewards.give.help": "পুরস্কার একজন দলের সদস্যের কাছে যায়। ম্যানেজাররা কর্মীদের পুরস্কার দেন; মালিক দলের যেকোনো কাউকে পুরস্কার দিতে পারেন।",
