  "rewards.redeem.done": "পুরস্কার ব্যবহৃত হিসেবে চিহ্নিত হয়েছে।",
  "rewards.redeem.help": "দলের সদস্য আপনাকে যে কোড দেখান তা টাইপ করুন। প্রতিটি কোড একবার কাজ করে।",
