  "pos.csv.help": "সংযোগ নেই এমন একটি টিলের জন্য: দিনের বিক্রয় একটি CSV হিসেবে এক্সপোর্ট করুন এবং এখানে আপলোড করুন। প্রতিটি বিক্রয় একবার রেকর্ড হয় — একই ফাইল আবার আপলোড করলে কিছুই বদলায় না।",
