  "pos.toast.help": "Toast, Toast-এর পার্টনার প্রোগ্রামের মাধ্যমে সংযোগ করে। আপনার রেস্তোরাঁর পার্টনার ক্রেডেনশিয়াল প্রস্তুত হলে, সেগুলো এখানে পেস্ট করুন এবং প্রতিটি Toast বিক্রয় নিজে থেকেই এখানে এর আইটেম স্টক থেকে বের করে।",
