  "pos.lightspeed.help": "আপনার Lightspeed Retail (X-Series) স্টোরটি সংযোগ করুন এবং প্রতিটি সম্পূর্ণ বিক্রয় নিজে থেকেই এখানে এর আইটেম স্টক থেকে বের করে।",
